SELECT tblProviderServiceCatalog.ProviderID, tblProviderServiceCatalog.ServiceID, Min(tblProviderServiceCatalog.[FiscalYear]) AS MinFiscalYear, Max(tblProviderServiceCatalog.[FiscalYear]) AS MaxFiscalYear
FROM tblProviderServiceCatalog
GROUP BY tblProviderServiceCatalog.ProviderID, tblProviderServiceCatalog.ServiceID;
